"use strict";(self.webpackChunkenablemodel=self.webpackChunkenablemodel||[]).push([[849],{6164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"The E.N.A.B.L.E. Model","href":"/docs/intro","docId":"intro","unlisted":false},{"type":"category","label":"Pre-deployment Interventions","collapsible":true,"collapsed":false,"items":[{"type":"link","label":"Set (Requirements) that Include Accessibility","href":"/docs/pre-deployment/requirement-setting","docId":"pre-deployment/requirement-setting","unlisted":false},{"type":"link","label":"Create Accessible (Content)","href":"/docs/pre-deployment/content","docId":"pre-deployment/content","unlisted":false},{"type":"link","label":"(Design) Accessible Experiences","href":"/docs/pre-deployment/design","docId":"pre-deployment/design","unlisted":false},{"type":"link","label":"(Develop) Accessible Implementations","href":"/docs/pre-deployment/development","docId":"pre-deployment/development","unlisted":false},{"type":"link","label":"(Test) for Accessibility","href":"/docs/pre-deployment/qa-testing","docId":"pre-deployment/qa-testing","unlisted":false},{"type":"link","label":"(Triage) and Prioritize Accessibility Issues","href":"/docs/pre-deployment/triage","docId":"pre-deployment/triage","unlisted":false},{"type":"link","label":"(Iterate) to Address Shortcomings","href":"/docs/pre-deployment/iteration","docId":"pre-deployment/iteration","unlisted":false},{"type":"link","label":"Create (Stopgaps)","href":"/docs/pre-deployment/stopgaps","docId":"pre-deployment/stopgaps","unlisted":false}],"href":"/docs/category/pre-deployment-interventions"},{"type":"category","label":"Post-deployment Compensations","collapsible":true,"collapsed":false,"items":[{"type":"link","label":"Use (Assistive Technologies)","href":"/docs/post-deployment/assistive-technologies","docId":"post-deployment/assistive-technologies","unlisted":false},{"type":"link","label":"Augment with (Third-Party Tools)","href":"/docs/post-deployment/third-party-tools","docId":"post-deployment/third-party-tools","unlisted":false},{"type":"link","label":"Change (System Settings)","href":"/docs/post-deployment/system-settings","docId":"post-deployment/system-settings","unlisted":false},{"type":"link","label":"Create (Workarounds)","href":"/docs/post-deployment/user-workarounds","docId":"post-deployment/user-workarounds","unlisted":false},{"type":"link","label":"Use (Humans) for Assistance","href":"/docs/post-deployment/human-help","docId":"post-deployment/human-help","unlisted":false},{"type":"link","label":"Submit (Feedback) to Creators","href":"/docs/post-deployment/give-feedback","docId":"post-deployment/give-feedback","unlisted":false},{"type":"link","label":"Assert One\'s (Rights)","href":"/docs/post-deployment/assert-rights","docId":"post-deployment/assert-rights","unlisted":false},{"type":"link","label":"Stage a (Protest)","href":"/docs/post-deployment/protest","docId":"post-deployment/protest","unlisted":false},{"type":"link","label":"Switch to an (Alternative)","href":"/docs/post-deployment/switch-to-alternative","docId":"post-deployment/switch-to-alternative","unlisted":false}],"href":"/docs/category/post-deployment-compensations"},{"type":"link","label":"Media, Storytelling, and Advocacy","href":"/docs/media-and-advocacy","docId":"media-and-advocacy","unlisted":false},{"type":"category","label":"Manifestations","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Use Be My Eyes","href":"/docs/manifestations/be-my-eyes","docId":"manifestations/be-my-eyes","unlisted":false}],"href":"/docs/category/manifestations"}]},"docs":{"intro":{"id":"intro","title":"The E.N.A.B.L.E. Model","description":"A field guide for making accessibility happen  --  and for understanding what happens when it doesn\u2019t.","sidebar":"tutorialSidebar"},"manifestations/be-my-eyes":{"id":"manifestations/be-my-eyes","title":"Use Be My Eyes","description":"Be My Eyes connects blind users with volunteers or AI to help navigate inaccessible environments.","sidebar":"tutorialSidebar"},"media-and-advocacy":{"id":"media-and-advocacy","title":"Media, Storytelling, and Advocacy","description":"Media aren\'t just awareness tools  --  they\'re behavior change interventions.","sidebar":"tutorialSidebar"},"post-deployment/assert-rights":{"id":"post-deployment/assert-rights","title":"Assert One\'s (Rights)","description":"Asserting your rights means taking formal action to demand accessibility -- through legal complaints, policy escalation, or public accountability. It\u2019s a last-resort compensation when every other avenue has failed. It requires knowledge of the law, courage to speak up, and often, personal resources that many don\u2019t have.","sidebar":"tutorialSidebar"},"post-deployment/assistive-technologies":{"id":"post-deployment/assistive-technologies","title":"Use (Assistive Technologies)","description":"Assistive technologies are tools and devices that people with disabilities use to interact with digital and physical environments. These include screen readers, magnifiers, switch devices, Braille displays, speech recognition software, and more. When accessibility is not built into a product or service, users must rely on these tools to access information or complete tasks -- often bending them beyond their original intent.","sidebar":"tutorialSidebar"},"post-deployment/give-feedback":{"id":"post-deployment/give-feedback","title":"Submit (Feedback) to Creators","description":"When accessibility barriers block interaction, users may attempt to notify creators -- developers, designers, organizations -- that something is inaccessible or broken. This compensation shifts the burden to the end-user to identify issues, articulate them clearly, and hope for a response. Feedback can be submitted via email, forms, app stores, GitHub issues, or social media DMs \u2014 any place where creators might listen.","sidebar":"tutorialSidebar"},"post-deployment/human-help":{"id":"post-deployment/human-help","title":"Use (Humans) for Assistance","description":"This compensation occurs when a person with a disability must rely on another human being -- such as a friend, aide, stranger, or interpreter -- to complete a task they could have completed independently if accessibility had been ensured during design and development. This is not a request for help by choice, but a last resort in response to inaccessible systems.","sidebar":"tutorialSidebar"},"post-deployment/protest":{"id":"post-deployment/protest","title":"Stage a (Protest)","description":"Staging a protest is a last-resort form of advocacy when users -- especially disabled users -- encounter persistent, systemic inaccessibility with no recourse. Protests may be physical (sit-ins, marches), digital (social media campaigns, hashtag storms), or symbolic (boycotts, media attention). These actions are not planned parts of the product lifecycle -- they are triggered by continued neglect and exclusion.","sidebar":"tutorialSidebar"},"post-deployment/switch-to-alternative":{"id":"post-deployment/switch-to-alternative","title":"Switch to an (Alternative)","description":"Description","sidebar":"tutorialSidebar"},"post-deployment/system-settings":{"id":"post-deployment/system-settings","title":"Change (System Settings)","description":"Changing system or device settings refers to the manual configuration of accessibility features at the operating system level -- such as increasing text contrast, enabling screen magnifiers, turning on voice control, or adjusting keyboard input settings -- to make digital content usable. End-users resort to this when a website, app, or digital product fails to support their needs by default.","sidebar":"tutorialSidebar"},"post-deployment/third-party-tools":{"id":"post-deployment/third-party-tools","title":"Augment with (Third-Party Tools)","description":"When websites, apps, or systems are not accessible by default, end-users are often forced to install or activate third-party tools to bridge the gap. These tools may be browser extensions, overlay widgets, plugins, or standalone applications that provide missing accessibility functions like keyboard navigation, text-to-speech, or visual adjustments. These tools are not native to the experience -- they are compensations layered on top.","sidebar":"tutorialSidebar"},"post-deployment/user-workarounds":{"id":"post-deployment/user-workarounds","title":"Create (Workarounds)","description":"Workarounds are user-devised or community-shared solutions that bypass inaccessible features. These may include custom scripts, browser extensions, hacks, or alternative interaction flows. Users resort to them when accessibility was not adequately addressed during development, leaving them to \\"patch\\" access themselves.","sidebar":"tutorialSidebar"},"pre-deployment/content":{"id":"pre-deployment/content","title":"Create Accessible (Content)","description":"Creating accessible content means ensuring that the words, images, media, documents, and data presented to users can be perceived, understood, and interacted with by people with disabilities. This includes both the raw content (e.g., text, visuals, captions) and the formats in which that content is delivered.","sidebar":"tutorialSidebar"},"pre-deployment/design":{"id":"pre-deployment/design","title":"(Design) Accessible Experiences","description":"Designing accessible experiences means intentionally creating user interfaces, interactions, and flows that can be used equitably by people with disabilities. This includes considering a range of impairments (e.g., visual, auditory, cognitive, motor, speech) and ensuring the design works with assistive technologies, follows inclusive patterns, and avoids introducing unnecessary complexity or barriers.","sidebar":"tutorialSidebar"},"pre-deployment/development":{"id":"pre-deployment/development","title":"(Develop) Accessible Implementations","description":"This intervention focuses on the actual building of accessible technology, ensuring that products are implemented in ways that support inclusive use. It involves choosing the right tools, frameworks, markup, and logic to ensure the product\u2019s backend and frontend are functionally accessible.","sidebar":"tutorialSidebar"},"pre-deployment/iteration":{"id":"pre-deployment/iteration","title":"(Iterate) to Address Shortcomings","description":"Iteration is the process of making continuous improvements based on testing, feedback, and evaluation. In the context of accessibility, iteration means revisiting and refining digital systems, policies, or environments to resolve accessibility shortcomings discovered during development, QA, or after real-world use.","sidebar":"tutorialSidebar"},"pre-deployment/qa-testing":{"id":"pre-deployment/qa-testing","title":"(Test) for Accessibility","description":"Testing for accessibility means evaluating digital products and experiences to ensure that people with disabilities can perceive, operate, understand, and interact with them. This includes both manual and automated evaluations, ideally conducted by or with disabled users.","sidebar":"tutorialSidebar"},"pre-deployment/requirement-setting":{"id":"pre-deployment/requirement-setting","title":"Set (Requirements) that Include Accessibility","description":"Role in the ENABLE Model","sidebar":"tutorialSidebar"},"pre-deployment/stopgaps":{"id":"pre-deployment/stopgaps","title":"Create (Stopgaps)","description":"Stopgaps are temporary, partial measures introduced by builders when full accessibility is not yet feasible. They are not polished or equivalent alternatives  --  they are acknowledged as incomplete. Yet they demonstrate care by reducing harm in the short term. Stopgaps do not replace the obligation to fully remediate; they buy time, reduce harm, and signal accountability.","sidebar":"tutorialSidebar"},"pre-deployment/triage":{"id":"pre-deployment/triage","title":"(Triage) and Prioritize Accessibility Issues","description":"After accessibility issues are discovered -- whether through audits, testing, or user feedback -- teams must assess their severity, impact, and urgency. This process, known as triage, is followed by prioritization, where decisions are made about which issues must be addressed immediately, which can wait, and which may never be resolved. This intervention ensures that accessibility is treated as essential, not optional.","sidebar":"tutorialSidebar"}}}}')}}]);